<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'; import { useRouter } from 'vue-router'; import { ApiError } from '@/api/client'; import { getJobExecutions, retryJobExecution, type JobsPayload } from '@/api/operations'; import { getSession } from '@/api/session';
const router = useRouter(); const data = ref<JobsPayload | null>(null); const error = ref<string | null>(null); const message = ref<string | null>(null); const filters = reactive({ q: '', status: '', type: '', queue: '' });
const load = async () => { try { const session = await getSession(); if (session.active_role?.code !== 'administrador') { await router.replace('/panel'); return; } data.value = await getJobExecutions(filters); } catch (reason) { error.value = reason instanceof ApiError ? reason.message : 'No se pudieron cargar los trabajos.'; } };
const retry = async (id: string) => { try { message.value = (await retryJobExecution(id)).message; await load(); } catch (reason) { error.value = reason instanceof ApiError ? reason.message : 'No se pudo reintentar el trabajo.'; } };
onMounted(() => { void load(); });
</script>
<template><main class="app-page"><header class="app-header"><div><p class="eyebrow">Administración</p><h1>Trabajos asíncronos</h1><p>IA, documentos y notificaciones procesados en segundo plano.</p></div><RouterLink class="back-link" to="/panel">Volver al panel</RouterLink></header><form class="filter-form" @submit.prevent="load"><label>Buscar<input v-model="filters.q" /></label><label>Estado<select v-model="filters.status"><option value="">Todos</option><option value="pendiente">Pendiente</option><option value="procesando">Procesando</option><option value="completada">Completada</option><option value="fallida">Fallida</option></select></label><label>Tipo<select v-model="filters.type"><option value="">Todos</option><option v-for="option in data?.type_options" :key="option.value" :value="option.value">{{ option.label }}</option></select></label><label>Cola<select v-model="filters.queue"><option value="">Todas</option><option v-for="option in data?.queue_options" :key="option.value" :value="option.value">{{ option.label }}</option></select></label><button>Aplicar</button></form><p v-if="message" class="save-status">{{ message }}</p><p v-if="error" role="alert">{{ error }}</p><div v-if="data" class="table-wrap"><table><thead><tr><th>Tipo</th><th>Cola</th><th>Estado</th><th>Intentos</th><th>Progreso</th><th>Error</th><th></th></tr></thead><tbody><tr v-for="job in data.executions.data" :key="job.id"><td>{{ job.tipo }}</td><td>{{ job.cola }}</td><td>{{ job.estado }}</td><td>{{ job.intentos }}/{{ job.intentos_maximos }}</td><td>{{ job.progreso }}%</td><td>{{ job.mensaje_error }}</td><td><button v-if="job.reintentable" @click="retry(job.id)">Reintentar</button></td></tr></tbody></table></div></main></template>
